import socket
import uuid
import threading
from queue import Queue, Empty
import paho.mqtt.client as mqtt
import base64
import os
from utils.db_utils import execute_query
from datetime import datetime, timedelta
from utils.common_utils import timedelta_to_time
from utils.anpr_ocr import detect_and_ocr

BROKER_HOST = "broker.hivemq.com"
BROKER_PORT = 1883

SERVER_CONFIG_TOPIC = "2026091519991228/SERVER_CONFIG"
NOTIFICATION_TOPIC = "2026091519991228/NOTIFICATION"

ESP32_CAM_ENTRY_IMAGE_TOPIC = "2026091519991228/ESP32_CAM_ENTRY/IMAGE"
ESP32_CAM_ENTRY_SERVO_TOPIC = "2026091519991228/ESP32_CAM_ENTRY/SERVO"
NODE_MCU_ENTRY_DISPLAY_TOPIC = "2026091519991228/GT_DISPLAY/1"

ESP32_CAM_EXIT_IMAGE_TOPIC = "2026091519991228/ESP32_CAM_EXIT/IMAGE"
ESP32_CAM_EXIT_SERVO_TOPIC = "2026091519991228/ESP32_CAM_EXIT/SERVO"
NODE_MCU_EXIT_DISPLAY_TOPIC = "2026091519991228/GT_DISPLAY/2"

NODE_MCU_IR_SENSOR_1_TOPIC = "2026091519991228/UPDATE_PARKING_SLOT/1"
NODE_MCU_IR_SENSOR_2_TOPIC = "2026091519991228/UPDATE_PARKING_SLOT/2"
NODE_MCU_IR_SENSOR_3_TOPIC = "2026091519991228/UPDATE_PARKING_SLOT/3"
NODE_MCU_IR_SENSOR_4_TOPIC = "2026091519991228/UPDATE_PARKING_SLOT/4"

test_image_base_64_str = ""

def get_system_ip():
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.connect(("8.8.8.8", 80))
        ip = sock.getsockname()[0]
        print(f"System LAN IP detected: {ip}")
        return ip
    except Exception as e:
        print(f"Failed to get system IP: {e}")
        return "127.0.0.1"
    finally:
        sock.close()

class MQTTManager:
    def __init__(self, app):
        self.app = app
        self.client_id = f"flask_{uuid.uuid4().hex}"
        self.client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2, client_id=self.client_id)

        self.client.on_connect = self.on_connect
        self.client.on_disconnect = self.on_disconnect
        self.client.on_message = self.on_message

        self.client.reconnect_delay_set(min_delay=1,max_delay=30)

        self.pending_messages = Queue()

        self.connected_event = threading.Event()

        self._stopped = False
        self._started = False

        print(f"MQTT client created | client_id={self.client_id}")

    def on_message(self, client, userdata, msg):
        print("MQTT MESSAGE RECEIVED || ", msg.topic, " || ", msg.payload.decode("utf-8"), " || qos=", msg.qos)
        if msg.topic == ESP32_CAM_ENTRY_IMAGE_TOPIC:
            self.publish(NODE_MCU_ENTRY_DISPLAY_TOPIC, "Image recieved...")
            # image_path = self.base64_to_image(msg.payload.decode("utf-8"))
            image_path = self.base64_to_image(test_image_base_64_str)
            vehicle_number = detect_and_ocr(image_path=image_path)
            self.process_booking_image(vehicle_number, NODE_MCU_ENTRY_DISPLAY_TOPIC, ESP32_CAM_ENTRY_SERVO_TOPIC)

        if msg.topic == ESP32_CAM_EXIT_IMAGE_TOPIC: 
            self.publish(NODE_MCU_EXIT_DISPLAY_TOPIC, "Image recieved...")
            image_path = self.base64_to_image(msg.payload.decode("utf-8"))
            vehicle_number = detect_and_ocr(image_path=image_path)
            self.process_booking_image(vehicle_number, NODE_MCU_EXIT_DISPLAY_TOPIC, ESP32_CAM_EXIT_SERVO_TOPIC)

        if msg.topic == NODE_MCU_IR_SENSOR_1_TOPIC or msg.topic == NODE_MCU_IR_SENSOR_2_TOPIC or msg.topic == NODE_MCU_IR_SENSOR_3_TOPIC or msg.topic == NODE_MCU_IR_SENSOR_4_TOPIC:
            sensor_slot_mapping = {NODE_MCU_IR_SENSOR_1_TOPIC:101, NODE_MCU_IR_SENSOR_2_TOPIC:102, NODE_MCU_IR_SENSOR_3_TOPIC:103, NODE_MCU_IR_SENSOR_4_TOPIC:104}
            is_available = int(1 if msg.payload.decode("utf-8") == "available" else 0)
            with self.app.app_context():
                query = "UPDATE car_parking.parking_slots SET is_available = %s WHERE slot_number = %s;"
                execute_query(query=query, args=(is_available, sensor_slot_mapping.get(msg.topic)))

    def base64_to_image(self, base64_string):
        try:
            if "," in base64_string:
                base64_string = base64_string.split(",", 1)[1]
            image_data = base64.b64decode(base64_string)
            filename = f"vehicle_image{uuid.uuid4().hex}.jpg"
            image_dir = os.path.join("static", "images")
            os.makedirs(image_dir, exist_ok=True)
            image_path = os.path.join(image_dir, filename)
            with open(image_path, "wb") as f:
                f.write(image_data)
            print(f"Image saved: {image_path}")
            return image_path
        except Exception as e:
            print(f"Error converting Base64 to image: {e}")
            return None

    def process_booking_image(self, plate_number, display_topic, servo_topic):
        try:
            self.publish(display_topic, "check booking...")
            print("Extracted plate number:", plate_number)
            result = None
            with self.app.app_context():
                result = execute_query('''SELECT DATE(a.booking_date) as booking_date, a.start_time, a.end_time FROM car_parking.booking as a inner join vehicle_details as b on a.vehicle_id = b.ID where (extracted_number = %s OR number = %s);''', args=(plate_number,plate_number,), is_fetchone=True)

                self.publish(servo_topic,"OPEN")
                return "OPEN"

                if result:
                    print(f"booking found for plate number: {plate_number} >> {result}")
                    current_datetime = datetime.now()
                    current_date = current_datetime.date()
                    current_time = current_datetime.time()
                    booking_date = result["booking_date"]
                    if booking_date != current_date:
                        print(f"Booking date mismatch | booking={booking_date} | current={current_date}")
                        self.publish(display_topic, "Booking date mismatch")
                        return None

                    start_time = result["start_time"]
                    end_time = result["end_time"]

                    if isinstance(start_time, timedelta):
                        start_time = timedelta_to_time(start_time)

                    if isinstance(end_time, timedelta):
                        end_time = timedelta_to_time(end_time)

                    if start_time <= current_time <= end_time:
                        print(f"VALID BOOKING | vehicle={plate_number} | time={current_time}")
                        self.publish(servo_topic,"OPEN")
                        return "OPEN"
                    else:
                        print(f"Booking time mismatch | current={current_time} | start={start_time} | end={end_time}")
                        self.publish(display_topic,"Booking time mismatch, try to open from app.")
                        return None
                else:
                    print(f"No booking found for plate number: {plate_number}")
                    self.publish(display_topic,"No booking found for plate number")
            return result
        except Exception as e:
            print(f"Failed to decode/save IoT image: {e}")
            self.publish(display_topic, "Error processing image")
            return None

    def start(self):
        if self._started:
            return
        try:
            self._stopped = False
            print(f"Starting MQTT | broker={BROKER_HOST}:{BROKER_PORT} | client_id={self.client_id}")
            self.client.loop_start()
            self._started = True
            self.client.connect_async(BROKER_HOST,BROKER_PORT,keepalive=60)
            print("MQTT connection initiated")
        except Exception as e:
            print(f"MQTT start failed: {e}")

    def ensure_connected(self, timeout=10):
        if self.client.is_connected():
            print("MQTT already connected")
            return True
        print("MQTT is not connected. Starting connection...")
        self.connected_event.clear()
        if not self._started:
            self.start()
        else:
            try:
                print("Requesting MQTT reconnect...")
                self.client.reconnect()
            except Exception as e:
                print(f"Immediate reconnect failed: {e}")

        print(f"Waiting for MQTT connection (timeout={timeout}s)...")
        connected = self.connected_event.wait(timeout=timeout)
        if connected and self.client.is_connected():
            print("MQTT connection established")
            return True
        print("MQTT connection timeout/failed")
        return False

    def on_connect(self, client, userdata, flags, reason_code, properties):
        print(f"MQTT CONNECT CALLBACK | client_id={self.client_id} | reason_code={reason_code}")
        if reason_code.is_failure:
            print(f"MQTT connection failed | reason={reason_code}")
            self.connected_event.clear()
            return
        print("MQTT connected successfully")
        self.connected_event.set()

        result = client.subscribe(ESP32_CAM_ENTRY_IMAGE_TOPIC, qos=1)
        if result[0] == mqtt.MQTT_ERR_SUCCESS:
            print(f"Subscribed successfully | topic={ESP32_CAM_ENTRY_IMAGE_TOPIC}")
        else:
            print(f"Subscription failed | topic={ESP32_CAM_ENTRY_IMAGE_TOPIC}")

        result = client.subscribe(ESP32_CAM_EXIT_IMAGE_TOPIC, qos=1)
        if result[0] == mqtt.MQTT_ERR_SUCCESS:
            print(f"Subscribed successfully | topic={ESP32_CAM_EXIT_IMAGE_TOPIC}")
        else:
            print(f"Subscription failed | topic={ESP32_CAM_EXIT_IMAGE_TOPIC}")

        result = client.subscribe(NODE_MCU_IR_SENSOR_1_TOPIC, qos=1)
        if result[0] == mqtt.MQTT_ERR_SUCCESS:
            print(f"Subscribed successfully | topic={NODE_MCU_IR_SENSOR_1_TOPIC}")
        else:
            print(f"Subscription failed | topic={NODE_MCU_IR_SENSOR_1_TOPIC}")

        result = client.subscribe(NODE_MCU_IR_SENSOR_2_TOPIC, qos=1)
        if result[0] == mqtt.MQTT_ERR_SUCCESS:
            print(f"Subscribed successfully | topic={NODE_MCU_IR_SENSOR_2_TOPIC}")
        else:
            print(f"Subscription failed | topic={NODE_MCU_IR_SENSOR_2_TOPIC}")

        result = client.subscribe(NODE_MCU_IR_SENSOR_3_TOPIC, qos=1)
        if result[0] == mqtt.MQTT_ERR_SUCCESS:
            print(f"Subscribed successfully | topic={NODE_MCU_IR_SENSOR_3_TOPIC}")
        else:
            print(f"Subscription failed | topic={NODE_MCU_IR_SENSOR_3_TOPIC}")

        result = client.subscribe(NODE_MCU_IR_SENSOR_4_TOPIC, qos=1)
        if result[0] == mqtt.MQTT_ERR_SUCCESS:
            print(f"Subscribed successfully | topic={NODE_MCU_IR_SENSOR_4_TOPIC}")
        else:
            print(f"Subscription failed | topic={NODE_MCU_IR_SENSOR_4_TOPIC}")

        self.publish_server_config()
        self.publish_pending_messages()

    def publish_server_config(self):
        if not self.client.is_connected():
            print("Cannot publish SERVER_CONFIG. MQTT is disconnected.")
            return False
        try:
            ip = get_system_ip()
            server_url = f"http://{ip}:5000/api/"
            result = self.client.publish(SERVER_CONFIG_TOPIC,server_url,qos=1,retain=True)
            if result.rc == mqtt.MQTT_ERR_SUCCESS:
                print(f"SERVER_CONFIG published | topic={SERVER_CONFIG_TOPIC} | url={server_url}")
                return True
            print(f"SERVER_CONFIG publish failed | rc={result.rc}")
            return False
        except Exception as e:
            print(f"SERVER_CONFIG publish exception: {e}")
            return False

    def on_disconnect(self,client,userdata,disconnect_flags,reason_code,properties):
        print(f"MQTT DISCONNECTED | reason_code={reason_code} | disconnect_flags={disconnect_flags}")
        self.connected_event.clear()
        if self._stopped:
            print("MQTT disconnected intentionally")
        else:
            print("MQTT disconnected unexpectedly. Automatic reconnect is enabled.")

    def publish(self,topic,message,qos=1,retain=False):
        print(f"MQTT publish requested | connected={self.client.is_connected()} | topic={topic}")

        if not self.client.is_connected():
            connected = self.ensure_connected(timeout=10)
            if not connected:
                print("Unable to connect to MQTT broker. Queueing message.")
                self.pending_messages.put((topic,message,qos,retain))
                print(f"Message added to pending queue | queue_size={self.pending_messages.qsize()}")
                return False
        try:
            result = self.client.publish(topic,message,qos=qos,retain=retain)
            if result.rc == mqtt.MQTT_ERR_SUCCESS:
                print(f"MQTT published successfully | topic={topic} | message={message}")
                return True
            print(f"MQTT publish failed | topic={topic} | rc={result.rc}")
            self.pending_messages.put((topic,message,qos,retain))
            return False
        except Exception as e:
            print(f"MQTT publish exception | topic={topic} | error={e}")
            self.pending_messages.put((topic,message,qos,retain))
            return False

    def publish_pending_messages(self):
        if not self.client.is_connected():
            print("Cannot publish pending messages. MQTT is disconnected.")
            return

        print(f"Checking pending MQTT messages | queue_size={self.pending_messages.qsize()}")
        while True:
            try:
                topic, message, qos, retain = (self.pending_messages.get_nowait())
            except Empty:
                break
            try:
                if not self.client.is_connected():
                    print("MQTT disconnected while processing pending queue.")
                    self.pending_messages.put((topic,message,qos,retain))
                    self.pending_messages.task_done()
                    break
                result = self.client.publish(topic,message,qos=qos,retain=retain)
                if result.rc == mqtt.MQTT_ERR_SUCCESS:
                    print(f"Queued MQTT message published | topic={topic}")
                    self.pending_messages.task_done()
                else:
                    print(f"Queued MQTT message publish failed | topic={topic} | rc={result.rc}")
                    self.pending_messages.put((topic,message,qos,retain))
                    self.pending_messages.task_done()
                    break
            except Exception as e:
                print(f"Error publishing queued MQTT message | topic={topic} | error={e}")
                self.pending_messages.put((topic,message,qos,retain))
                self.pending_messages.task_done()
                break
        print(f"Pending MQTT queue after processing: {self.pending_messages.qsize()}")

    def stop(self):
        try:
            print("Stopping MQTT manager...")
            self._stopped = True
            self.connected_event.clear()
            if self.client.is_connected():
                print("Disconnecting MQTT...")
                self.client.disconnect()
            if self._started:
                self.client.loop_stop()
                self._started = False
            print("MQTT stopped successfully")
        except Exception as e:
            print(f"MQTT stop failed: {e}")